/* ==========================================================================
   8. PURE CSS & MULTI-PLANE 3D HERO BACKGROUND SCENE ENGINE
      - Replaces /assets/file_ab2082.png with 100% code-driven CSS + 3D layers
      - Inpainted background base (--wm-hero-3d-bg-healed) so floating 3D
        balloons, gift box, and stars have zero double-image ghosting
      - Continuous background floating animation + touch/tap/drag responsiveness
      - Mobile view (< 768px) shifted left so the full gift box & balloons show
   ========================================================================== */
:root {
  --wm-hero-3d-bg-healed: url("data:image/webp;base64,");
  --wm-hero-3d-composite: url("data:image/webp;base64,");
  --wm-hero-3d-box-layer: url("data:image/webp;base64,");
  --wm-hero-3d-balloons-back-layer: url("data:image/webp;base64,");
  --wm-hero-3d-balloons-mid-layer: url("data:image/webp;base64,");
  --wm-hero-3d-balloons-front-layer: url("data:image/webp;base64,");
  --wm-hero-3d-stars-layer: url("data:image/webp;base64,");
  --wm-3d-tilt-x: 0deg;
  --wm-3d-tilt-y: 0deg;
  --wm-3d-px: 0px;
  --wm-3d-py: 0px;
  --wm-hero-canvas-anchor-x: -46.0%;
}

@media (min-width: 768px) and (max-width: 1199.98px) {
  :root {
    --wm-hero-canvas-anchor-x: -48.8%;
  }
}

/* Mobile View (< 768px) kept 100% untouched! */
@media (max-width: 767.98px) {
  :root {
    --wm-hero-canvas-anchor-x: -57.5%;
  }
}

@media (max-width: 479.98px) {
  :root {
    --wm-hero-canvas-anchor-x: -58.2%;
  }
}

#hero-desktop-section.hero-desktop-canvas {
  background-image: none !important;
  background-color: #160536 !important;
  touch-action: pan-y;
}

.hero-css-3d-viewport {
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  overflow: hidden !important;
  pointer-events: none !important;
  z-index: 0 !important;
  perspective: 1100px;
  perspective-origin: 50% 50%;
}

.hero-css-3d-canvas {
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  height: 100% !important;
  width: auto !important;
  min-width: 100% !important;
  aspect-ratio: 1600 / 533 !important;
  transform: translate3d(var(--wm-hero-canvas-anchor-x, -44.2%), -50%, 0) rotateX(var(--wm-3d-tilt-x, 0deg)) rotateY(var(--wm-3d-tilt-y, 0deg));
  transform-style: preserve-3d;
  transition: transform 0.32s cubic-bezier(0.22, 1, 0.36, 1);
  will-change: transform;
}

@media (min-width: 768px) {
  .hero-css-3d-canvas {
    min-width: 112% !important;
    min-height: 100% !important;
  }
}

/* Full-canvas 3D Parallax Planes (driven by mouse/touch drag & tap) */
.hero-3d-plane {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  transform-origin: 66% 55%;
  pointer-events: none;
  transition: transform 0.38s cubic-bezier(0.34, 1.56, 0.64, 1), filter 0.35s ease;
  will-change: transform;
}

/* Healed Background Base (Sky, Spiral Galaxy, Castles, Clouds & 3D Cloud Orbs) */
.hero-3d-bg-base {
  position: absolute;
  inset: 0;
  background-image: var(--wm-hero-3d-bg-healed);
  background-size: 100% 100%;
  background-repeat: no-repeat;
  transform: translate3d(calc(var(--wm-3d-px, 0px) * -0.15), calc(var(--wm-3d-py, 0px) * -0.15), 0px);
  transition: transform 0.38s cubic-bezier(0.22, 1, 0.36, 1);
}

/* Pure CSS Cosmic Galaxy & Horizon Volumetric Atmosphere Overlay */
.hero-3d-css-atmosphere {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 18% 22% at 73.2% 20.8%, rgba(255, 240, 195, 0.16) 0%, rgba(244, 114, 182, 0.08) 45%, transparent 75%),
    radial-gradient(ellipse 14% 16% at 67.5% 68.5%, rgba(255, 250, 205, 0.22) 0%, rgba(251, 191, 36, 0.10) 42%, transparent 72%);
  mix-blend-mode: screen;
  pointer-events: none;
}

/* Interactive Touch/Mouse Parallax Multipliers per 3D Depth Plane */
.hero-3d-plane-box     { transform: translate3d(calc(var(--wm-3d-px, 0px) * 0.45), calc(var(--wm-3d-py, 0px) * 0.45), 0px); }
.hero-3d-plane-light   { transform: translate3d(calc(var(--wm-3d-px, 0px) * 0.55), calc(var(--wm-3d-py, 0px) * 0.55), 0px); }
.hero-3d-plane-b-back  { transform: translate3d(calc(var(--wm-3d-px, 0px) * 0.75), calc(var(--wm-3d-py, 0px) * 0.75), 0px); }
.hero-3d-plane-b-mid   { transform: translate3d(calc(var(--wm-3d-px, 0px) * 1.00), calc(var(--wm-3d-py, 0px) * 1.00), 0px); }
.hero-3d-plane-b-front { transform: translate3d(calc(var(--wm-3d-px, 0px) * 1.30), calc(var(--wm-3d-py, 0px) * 1.30), 0px); }
.hero-3d-plane-stars   { transform: translate3d(calc(var(--wm-3d-px, 0px) * 1.45), calc(var(--wm-3d-py, 0px) * 1.45), 0px); }
.hero-3d-plane-spec    { transform: translate3d(calc(var(--wm-3d-px, 0px) * 1.30), calc(var(--wm-3d-py, 0px) * 1.30), 0px); }

/* WishMagic Theme-Matched Touch/Click Confetti & Magical Celebration Burst Overlay */
.wm-hero-confetti-stage {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  pointer-events: none;
  z-index: 6;
}

.wm-confetti-piece {
  position: absolute;
  pointer-events: none;
  will-change: transform, opacity;
  animation: wmConfettiBurst var(--wm-cf-dur, 1150ms) cubic-bezier(0.18, 0.82, 0.28, 1) forwards;
}

