  filter: saturate(1.06) contrast(1.03);
}

/* Warm Ambient Golden Palace & Table Glow Layer */
.hero-diwali-ambient-glow {
  position: absolute;
  inset: 0;
  pointer-events: none;
  mix-blend-mode: screen;
  background:
    radial-gradient(circle 28% at 70% 68%, rgba(251, 191, 36, 0.14) 0%, transparent 70%),
