  --wm-cracker-color-2: #38bdf8;
  --wm-cracker-delay: 10.0s;
}

/* Rising Rocket Streak before each Cracker Burst */
.wm-cracker-rocket {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 3px;
  height: 72%;
  margin-left: -1.5px;
  border-radius: 999px;
  background: linear-gradient(to top, rgba(251, 191, 36, 0) 0%, rgba(251, 191, 36, 0.85) 55%, #ffffff 100%);
  box-shadow: 0 0 10px 2px rgba(253, 224, 71, 0.85);
  opacity: 0;
  transform-origin: 50% 0%;
  animation: wmCrackerRocketLaunch 12.5s cubic-bezier(0.2, 0.8, 0.3, 1) infinite;
  animation-delay: var(--wm-cracker-delay, 0s);
}

/* Central Ignition Flash Bloom */
.wm-cracker-flash {
  position: absolute;
  inset: -25%;
  border-radius: 50%;
  mix-blend-mode: screen;
  background: radial-gradient(
    circle,
    #ffffff 0%,
    var(--wm-cracker-color-1, #fde047) 22%,
    var(--wm-cracker-color-2, #f472b6) 46%,
    transparent 72%
  );
  opacity: 0;
  animation: wmCrackerFlashBloom 12.5s ease-out infinite;
  animation-delay: var(--wm-cracker-delay, 0s);
}

/* Expanding Photorealistic + Pure CSS Radial Firework Shell */
.wm-cracker-burst {
  position: absolute;
  inset: 0;
  background-image: var(--wm-cracker-shell-img);
  background-size: 100% 100%;
  background-position: center;
  background-repeat: no-repeat;
  mix-blend-mode: screen;
  filter: drop-shadow(0 0 12px var(--wm-cracker-color-1, #fde047)) brightness(1.18) saturate(1.22);
  opacity: 0;
  transform-origin: 50% 50%;
  animation: wmCrackerBurstExpand 12.5s cubic-bezier(0.16, 0.84, 0.32, 1) infinite;
  animation-delay: var(--wm-cracker-delay, 0s);
}

/* Pure CSS Radial Spark Rays & Glittering Tips inside .wm-cracker-burst */
.wm-cracker-burst::before {
  content: "";
  position: absolute;
  inset: 4%;
  border-radius: 50%;
  background:
    radial-gradient(circle, transparent 32%, rgba(255, 255, 255, 0.85) 48%, var(--wm-cracker-color-1, #fde047) 56%, transparent 70%),
    repeating-conic-gradient(
      from 0deg,
      var(--wm-cracker-color-1, #fde047) 0deg 1.8deg,
      transparent 1.8deg 15deg,
      var(--wm-cracker-color-2, #f472b6) 15deg 16.8deg,
      transparent 16.8deg 30deg
    );
  -webkit-mask-image: radial-gradient(circle, transparent 12%, #000 35%, #000 66%, transparent 74%);
  mask-image: radial-gradient(circle, transparent 12%, #000 35%, #000 66%, transparent 74%);
  mix-blend-mode: screen;
  opacity: 0.85;
}

.wm-cracker-burst::after {
  content: "";
  position: absolute;
  inset: 12%;
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 6%, #fff 0%, var(--wm-cracker-color-1) 2.5%, transparent 4%),
    radial-gradient(circle at 82% 18%, #fff 0%, var(--wm-cracker-color-2) 2.5%, transparent 4%),
    radial-gradient(circle at 94% 50%, #fff 0%, var(--wm-cracker-color-1) 2.5%, transparent 4%),
    radial-gradient(circle at 82% 82%, #fff 0%, var(--wm-cracker-color-2) 2.5%, transparent 4%),
    radial-gradient(circle at 50% 94%, #fff 0%, var(--wm-cracker-color-1) 2.5%, transparent 4%),
    radial-gradient(circle at 18% 82%, #fff 0%, var(--wm-cracker-color-2) 2.5%, transparent 4%),
    radial-gradient(circle at 6% 50%, #fff 0%, var(--wm-cracker-color-1) 2.5%, transparent 4%),
    radial-gradient(circle at 18% 18%, #fff 0%, var(--wm-cracker-color-2) 2.5%, transparent 4%);
  filter: drop-shadow(0 0 6px #ffffff);
}

/* ==========================================================================
   PLANE 3: 3D FLOATING SKY LANTERNS (With Inner Warm Flame Pulse)
   ========================================================================== */
.hero-diwali-plane-lanterns {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
  transform: translate3d(
    calc(var(--wm-3d-tilt-x, 0px) * 0.45),
    calc(var(--wm-3d-tilt-y, 0px) * 0.45),
    34px
  );
  transition: transform 0.2s cubic-bezier(0.22, 1, 0.36, 1);
}

.wm-diwali-lantern {
  position: absolute;
  background-size: 100% 100%;
  background-position: center;
  background-repeat: no-repeat;
  filter: drop-shadow(0 8px 20px rgba(249, 115, 22, 0.38));
  will-change: transform;
}

/* Warm flickering inner flame glow at the bottom of each floating sky lantern */
.wm-diwali-lantern::after {
  content: "";
  position: absolute;
  left: 28%;
  bottom: 8%;
  width: 44%;
  height: 36%;
  border-radius: 50%;
  mix-blend-mode: screen;
  background: radial-gradient(circle, rgba(255, 255, 220, 0.92) 0%, rgba(251, 191, 36, 0.65) 45%, transparent 78%);
  animation: wmDiyaHaloPulse 1.7s ease-in-out infinite alternate;
}

.wm-diwali-lantern-main {
  left: 29.5%;
  top: 2.8%;
  width: 10.3%;
  height: 19.6%;
  background-image: var(--wm-diwali-3d-lantern-main);
  animation: wmFloatDiwaliLanternMain 4.6s ease-in-out infinite alternate;
}

.wm-diwali-lantern-mid {
  left: 40.4%;
  top: 7.6%;
  width: 4.6%;
  height: 9.6%;
  background-image: var(--wm-diwali-3d-lantern-mid);
  animation: wmFloatDiwaliLanternMid 5.4s ease-in-out infinite alternate;
}

.wm-diwali-lantern-right {
  left: 77.6%;
  top: 2.4%;
  width: 7.8%;
  height: 15.0%;
  background-image: var(--wm-diwali-3d-lantern-right);
  animation: wmFloatDiwaliLanternRight 4.9s ease-in-out infinite alternate;
}

/* ==========================================================================
   PLANE 4: 3D FLOATING "WISHMAGIC HAPPY DIWALI" BOOK & COVER DIYA
   ========================================================================== */
.hero-diwali-plane-book {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
  transform: translate3d(
    calc(var(--wm-3d-tilt-x, 0px) * 0.62),
    calc(var(--wm-3d-tilt-y, 0px) * 0.62),
    50px
  );
  transition: transform 0.18s cubic-bezier(0.22, 1, 0.36, 1);
}

.hero-diwali-book-layer {
  position: absolute;
  left: 56.8%;
  top: 38.2%;
  width: 31.0%;
  height: 47.6%;
  background-image: var(--wm-diwali-3d-book-layer);
  background-size: 100% 100%;
  background-position: center;
  background-repeat: no-repeat;
  filter: drop-shadow(0 16px 28px rgba(10, 3, 24, 0.68)) drop-shadow(0 0 22px rgba(245, 158, 11, 0.22));
  transform-style: preserve-3d;
  animation: wmFloatDiwaliBook3D 4.4s ease-in-out infinite alternate;
}

/* Plane 5: 3D Swaying Marigold Garlands on the Palace Arch */
.hero-diwali-plane-garlands {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
  transform: translate3d(
    calc(var(--wm-3d-tilt-x, 0px) * 0.78),
    calc(var(--wm-3d-tilt-y, 0px) * 0.78),
    64px
  );
  transition: transform 0.18s cubic-bezier(0.22, 1, 0.36, 1);
}

.hero-diwali-garlands-layer {
  position: absolute;
  left: 86.2%;
  top: 0%;
  width: 7.6%;
  height: 42.2%;
  background-image: var(--wm-diwali-3d-garlands-layer);
  background-size: 100% 100%;
  background-position: top center;
  background-repeat: no-repeat;
  transform-origin: 50% 0%;
  filter: drop-shadow(0 10px 18px rgba(18, 5, 28, 0.55));
  animation: wmSwayDiwaliGarlands3D 3.8s ease-in-out infinite alternate;
}

/* ==========================================================================
   PLANE 6: REAL BURNING 3D CSS DIYAS & FLICKERING FLAMES
   Multi-layered teardrop CSS flames (white-hot wick core + golden-orange flame
   + dancing tip + warm radial light bloom + rising micro-sparks)
   ========================================================================== */
.hero-diwali-plane-diyas {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
  transform: translate3d(
    calc(var(--wm-3d-tilt-x, 0px) * 0.88),
    calc(var(--wm-3d-tilt-y, 0px) * 0.88),
    74px
  );
  transition: transform 0.16s cubic-bezier(0.22, 1, 0.36, 1);
}

.wm-diwali-diya {
  position: absolute;
  transform: translate(-50%, -90%);
  transform-origin: 50% 90%;
  pointer-events: none;
  z-index: 5;
}

/* Warm pulsing light cast onto the brass diya bowl & surrounding petals */
.wm-diya-halo {
  position: absolute;
  left: -140%;
  top: -70%;
  width: 380%;
  height: 250%;
  border-radius: 50%;
  mix-blend-mode: screen;
  background: radial-gradient(
    circle at 50% 58%,
    rgba(255, 215, 90, 0.68) 0%,
    rgba(251, 146, 60, 0.36) 38%,
    rgba(234, 88, 12, 0.12) 62%,
    transparent 80%
  );
  animation: wmDiyaHaloPulse 1.55s ease-in-out infinite alternate;
}

/* Main Teardrop Burning Flame Body */
.wm-diya-flame {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 50% 50% 38% 38% / 68% 68% 32% 32%;
  background: radial-gradient(
    ellipse at 50% 76%,
    #ffffff 0%,
    #fef9c3 24%,
    #fde047 46%,
    #fb923c 72%,
    rgba(234, 88, 12, 0.15) 92%,
    transparent 100%
  );
  box-shadow:
    0 0 10px 2px rgba(253, 224, 71, 0.92),
    0 -4px 16px 4px rgba(249, 115, 22, 0.72),
    0 -10px 26px 6px rgba(234, 88, 12, 0.38);
  transform-origin: 50% 90%;
  animation: wmDiyaBurnA 1.68s ease-in-out infinite alternate;
}

/* Pointed Dancing Flame Tip (whips gently with air currents) */
.wm-diya-flame::before {
  content: "";
  position: absolute;
  left: 18%;
  top: -22%;
  width: 64%;
  height: 62%;
  border-radius: 50% 50% 45% 45% / 78% 78% 22% 22%;
  background: linear-gradient(
    to top,
    rgba(253, 224, 71, 0.95) 0%,
    rgba(249, 115, 22, 0.85) 55%,
    rgba(234, 88, 12, 0) 100%
  );
  filter: blur(0.6px);
  transform-origin: 50% 100%;
  animation: wmDiyaTipWhip 0.82s ease-in-out infinite alternate;
}

/* White-Hot Inner Wick Core */
.wm-diya-flame::after {
  content: "";
  position: absolute;
  left: 24%;
  bottom: 5%;
  width: 52%;
  height: 48%;
  border-radius: 50% 50% 42% 42%;
  background: radial-gradient(
    ellipse at 50% 80%,
    #ffffff 0%,
    #fef08a 68%,
    transparent 100%
  );
  filter: drop-shadow(0 0 4px #ffffff);
}

/* Rising Golden Ember Micro-Spark above each Diya */
.wm-diya-spark {
  position: absolute;
  left: 44%;
  top: -12%;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: #fef08a;
  box-shadow: 0 0 6px 2px #f59e0b;
  opacity: 0;
  animation: wmDiyaSparkRise 2.1s ease-out infinite;
}

/* Exact Sub-Pixel Wick Coordinates & Organic Non-Synchronized Flame Timing for all 9 Diyas */
/* Diya 1: Left-bottom candle in brass bowl */
.wm-diya-1 {
  left: 31.42%;
  top: 84.40%;
  width: 1.35%;
  height: 3.85%;
}
.wm-diya-1 .wm-diya-flame { animation: wmDiyaBurnA 1.62s ease-in-out -0.2s infinite alternate; }
.wm-diya-1 .wm-diya-spark { animation-delay: 0.3s; }

/* Diya 2: Left-bottom sweets/laddoo thali diya */
.wm-diya-2 {
  left: 39.69%;
  top: 96.49%;
  width: 1.50%;
  height: 4.10%;
}
.wm-diya-2 .wm-diya-flame { animation: wmDiyaBurnB 1.84s ease-in-out -0.7s infinite alternate; }
.wm-diya-2 .wm-diya-spark { animation-delay: 1.1s; }

/* Diya 3: Center-left ornate carved brass diya */
.wm-diya-3 {
  left: 45.93%;
  top: 80.66%;
  width: 1.48%;
  height: 4.05%;
}
.wm-diya-3 .wm-diya-flame { animation: wmDiyaBurnC 1.74s ease-in-out -1.1s infinite alternate; }
.wm-diya-3 .wm-diya-spark { animation-delay: 0.6s; }

/* Diya 4: Mid-left brass bowl diya next to book */
.wm-diya-4 {
  left: 53.01%;
  top: 72.26%;
  width: 1.45%;
  height: 4.45%;
}
.wm-diya-4 .wm-diya-flame { animation: wmDiyaBurnD 1.56s ease-in-out -0.4s infinite alternate; }
.wm-diya-4 .wm-diya-spark { animation-delay: 1.5s; }

/* Diya 5: Mid-left ornate brass lantern inner flame */
.wm-diya-5 {
  left: 55.59%;
  top: 69.29%;
  width: 1.25%;
  height: 3.40%;
}
.wm-diya-5 .wm-diya-flame { animation: wmDiyaBurnB 1.95s ease-in-out -0.9s infinite alternate; }
.wm-diya-5 .wm-diya-spark { animation-delay: 0.9s; }

/* Diya 6: 3D Book Cover Centerpiece Diya (Positioned inside .hero-diwali-book-layer so it floats with the book!) */
.wm-diya-6-book {
  left: 46.29%;
  top: 68.21%;
  width: 5.20%;
  height: 10.60%;
}
.wm-diya-6-book .wm-diya-flame { animation: wmDiyaBurnC 1.68s ease-in-out -0.5s infinite alternate; }
.wm-diya-6-book .wm-diya-spark { animation-delay: 0.2s; }

/* Diya 7: Front-center small golden diya in front of book */
.wm-diya-7 {
  left: 67.98%;
  top: 87.67%;
  width: 1.45%;
  height: 3.95%;
}
.wm-diya-7 .wm-diya-flame { animation: wmDiyaBurnA 1.79s ease-in-out -1.3s infinite alternate; }
.wm-diya-7 .wm-diya-spark { animation-delay: 1.4s; }

/* Diya 8: Front-right large hero foreground diya */
.wm-diya-8 {
  left: 80.65%;
  top: 88.63%;
  width: 1.85%;
  height: 5.95%;
}
.wm-diya-8 .wm-diya-flame { animation: wmDiyaBurnD 1.64s ease-in-out -0.8s infinite alternate; }
.wm-diya-8 .wm-diya-spark { animation-delay: 0.7s; }

/* Diya 9: Right ornate brass lantern inner flame behind gift boxes */
.wm-diya-9 {
  left: 89.85%;
  top: 65.67%;
  width: 1.65%;
  height: 5.20%;
}
.wm-diya-9 .wm-diya-flame { animation: wmDiyaBurnA 1.88s ease-in-out -1.5s infinite alternate; }
.wm-diya-9 .wm-diya-spark { animation-delay: 1.8s; }

/* When 3D floating is paused via Admin Settings, keep diyas flickering gently but pause heavy 3D layer bobbing */
#hero-desktop-section[data-hero-3d-floating="off"] .wm-diwali-lantern,
#hero-desktop-section[data-hero-3d-floating="off"] .hero-diwali-book-layer,
#hero-desktop-section[data-hero-3d-floating="off"] .hero-diwali-garlands-layer {
  animation: none !important;
}

/* ==========================================================================
   DIWALI 3D KEYFRAME ANIMATIONS (Real Burning Diyas, Sequential Crackers & 3D Float)
   ========================================================================== */
@keyframes wmDiyaBurnA {
  0%   { transform: scaleX(0.94) scaleY(0.93) skewX(-3.5deg) rotate(-2deg); filter: brightness(0.96); }
  25%  { transform: scaleX(1.04) scaleY(1.08) skewX(2.5deg) rotate(1.5deg); filter: brightness(1.08); }
  50%  { transform: scaleX(0.91) scaleY(1.14) skewX(-4.5deg) rotate(-3deg); filter: brightness(1.14); }
  75%  { transform: scaleX(1.06) scaleY(0.97) skewX(4.0deg) rotate(2.5deg); filter: brightness(1.02); }
  100% { transform: scaleX(0.96) scaleY(1.11) skewX(-2.0deg) rotate(-1.5deg); filter: brightness(1.12); }
}

@keyframes wmDiyaBurnB {
  0%   { transform: scaleX(1.03) scaleY(0.95) skewX(3.0deg) rotate(2deg); filter: brightness(0.98); }
  33%  { transform: scaleX(0.92) scaleY(1.12) skewX(-5.0deg) rotate(-3.5deg); filter: brightness(1.12); }
  66%  { transform: scaleX(1.05) scaleY(1.02) skewX(3.5deg) rotate(2deg); filter: brightness(1.04); }
  100% { transform: scaleX(0.95) scaleY(1.15) skewX(-3.0deg) rotate(-2deg); filter: brightness(1.15); }
}

@keyframes wmDiyaBurnC {
  0%   { transform: scaleX(0.96) scaleY(1.05) skewX(-2.0deg) rotate(-1deg); filter: brightness(1.04); }
  30%  { transform: scaleX(1.06) scaleY(0.92) skewX(4.5deg) rotate(3deg); filter: brightness(0.95); }
  65%  { transform: scaleX(0.90) scaleY(1.16) skewX(-4.0deg) rotate(-2.5deg); filter: brightness(1.16); }
  100% { transform: scaleX(1.02) scaleY(1.06) skewX(2.5deg) rotate(1.5deg); filter: brightness(1.08); }
}

@keyframes wmDiyaBurnD {
  0%   { transform: scaleX(0.93) scaleY(0.96) skewX(4.0deg) rotate(2.5deg); filter: brightness(0.97); }
  40%  { transform: scaleX(1.05) scaleY(1.14) skewX(-3.5deg) rotate(-2deg); filter: brightness(1.14); }
  70%  { transform: scaleX(0.94) scaleY(1.01) skewX(5.0deg) rotate(3.5deg); filter: brightness(1.01); }
  100% { transform: scaleX(1.01) scaleY(1.13) skewX(-4.5deg) rotate(-3deg); filter: brightness(1.12); }
}

@keyframes wmDiyaTipWhip {
  0%   { transform: translateX(-6%) skewX(-8deg) scaleY(0.92); }
  100% { transform: translateX(7%) skewX(9deg) scaleY(1.14); }
}

@keyframes wmDiyaHaloPulse {
  0%   { opacity: 0.76; transform: scale(0.92); }
  100% { opacity: 1.00; transform: scale(1.10); }
}

@keyframes wmDiyaSparkRise {
  0%   { opacity: 0; transform: translate3d(0, 4px, 0) scale(0.5); }
  20%  { opacity: 0.95; transform: translate3d(-2px, -6px, 0) scale(1.1); }
  65%  { opacity: 0.55; transform: translate3d(3px, -18px, 0) scale(0.8); }
  100% { opacity: 0; transform: translate3d(-1px, -28px, 0) scale(0.2); }
}

/* Sequential Cracker Animations (Each Cracker occupies ~21% of the 12.5s cycle = ~2.6s normal speed) */
@keyframes wmCrackerRocketLaunch {
  0%     { opacity: 0; transform: translate3d(0, 85px, 0) scaleY(0.2); }
  1.2%   { opacity: 1; transform: translate3d(0, 55px, 0) scaleY(0.85); }
  4.2%   { opacity: 0.95; transform: translate3d(0, 0px, 0) scaleY(0.45); }
  5.0%, 100% { opacity: 0; transform: translate3d(0, -8px, 0) scaleY(0.1); }
}

@keyframes wmCrackerFlashBloom {
  0%, 3.8%   { opacity: 0; transform: scale(0.15); }
  5.2%       { opacity: 0.95; transform: scale(0.95); }
  8.5%       { opacity: 0.45; transform: scale(1.25); }
  13.5%, 100% { opacity: 0; transform: scale(1.4); }
}

@keyframes wmCrackerBurstExpand {
  0%, 3.8%   { opacity: 0; transform: translate3d(0, 0, 0) scale(0.14) rotate(-8deg); filter: brightness(1.8); }
  5.5%       { opacity: 1; transform: translate3d(0, 0, 0) scale(0.52) rotate(-3deg); filter: brightness(1.55); }
  12.0%      { opacity: 1; transform: translate3d(0, 0, 0) scale(1.00) rotate(2deg); filter: brightness(1.22); }
  16.5%      { opacity: 0.78; transform: translate3d(0, 4px, 0) scale(1.08) rotate(5deg); filter: brightness(1.08); }
  21.5%, 100% { opacity: 0; transform: translate3d(0, 11px, 0) scale(1.15) rotate(8deg); filter: brightness(0.8); }
}

/* 3D Floating Keyframes for Diwali Lanterns, Book & Garlands */
@keyframes wmFloatDiwaliLanternMain {
  0%   { transform: translate3d(-2px, 4px, 0) rotate(-1.4deg) scale(0.99); }
  100% { transform: translate3d(3px, -8px, 0) rotate(1.6deg) scale(1.02); }
}

@keyframes wmFloatDiwaliLanternMid {
  0%   { transform: translate3d(2px, 3px, 0) rotate(1.2deg); }
  100% { transform: translate3d(-2px, -7px, 0) rotate(-1.5deg); }
}

@keyframes wmFloatDiwaliLanternRight {
  0%   { transform: translate3d(-1.5px, 3.5px, 0) rotate(1.0deg) scale(0.995); }
  100% { transform: translate3d(2.5px, -7.5px, 0) rotate(-1.4deg) scale(1.015); }
}

@keyframes wmFloatDiwaliBook3D {
  0%   { transform: translate3d(0px, 2.5px, 0px) rotate(-0.35deg) scale(0.996); }
  100% { transform: translate3d(0px, -5.5px, 0px) rotate(0.45deg) scale(1.008); }
}

@keyframes wmSwayDiwaliGarlands3D {
  0%   { transform: rotate(-1.15deg) translate3d(-1px, 0, 0); }
  100% { transform: rotate(1.25deg) translate3d(1.5px, 0, 0); }
}

@keyframes wmDiwaliAmbientPulse {
  0%   { opacity: 0.72; }
  100% { opacity: 1.00; }
}
